const ease=bez(0.22,1,0.36,1)
const DUR=540,STEP=90,R=130,CUT=158,DISCS=[502,316,130]
const track=(p,stops)=>{if(p<=0)return stops[0].v;if(p>=1)return stops[stops.length-1].v
 for(let i=0;i<stops.length-1;i++){const a=stops[i],b=stops[i+1];if(p>=a.at&&p<=b.at){const f=ease((p-a.at)/(b.at-a.at));return a.v+f*(b.v-a.v)}}return stops[stops.length-1].v}
